-- Extend the persisted agent domain without editing historical migrations.
ALTER TABLE "Agent" ADD COLUMN "name" VARCHAR(160) NOT NULL DEFAULT '', ADD COLUMN "maxConcurrency" INTEGER NOT NULL DEFAULT 1, ADD COLUMN "maxOutputTokens" INTEGER NOT NULL DEFAULT 512, ADD COLUMN "inputRateMicrosPerMillion" BIGINT NOT NULL DEFAULT 0, ADD COLUMN "outputRateMicrosPerMillion" BIGINT NOT NULL DEFAULT 0, ADD COLUMN "lastRunAt" TIMESTAMPTZ(3);
ALTER TABLE "Agent" ADD CONSTRAINT "agent_runtime_limits" CHECK ("maxConcurrency" BETWEEN 1 AND 4 AND "maxOutputTokens" BETWEEN 64 AND 2048 AND "inputRateMicrosPerMillion">=0 AND "outputRateMicrosPerMillion">=0);
ALTER TABLE "AgentTask" ADD COLUMN "trigger" VARCHAR(20) NOT NULL DEFAULT 'MANUAL', ADD COLUMN "approvedConfigHash" CHAR(64), ADD COLUMN "leaseToken" UUID, ADD COLUMN "cancelRequestedAt" TIMESTAMPTZ(3), ADD COLUMN "resultApprovedAt" TIMESTAMPTZ(3), ADD COLUMN "errorCode" VARCHAR(100);
ALTER TABLE "AgentExecution" ADD COLUMN "provider" VARCHAR(30) NOT NULL DEFAULT 'LEGACY', ADD COLUMN "providerResponseId" VARCHAR(200) UNIQUE, ADD COLUMN "leaseToken" UUID, ADD COLUMN "reservedUsdMicros" BIGINT NOT NULL DEFAULT 0, ADD COLUMN "inputRateMicrosPerMillion" BIGINT NOT NULL DEFAULT 0, ADD COLUMN "outputRateMicrosPerMillion" BIGINT NOT NULL DEFAULT 0, ADD COLUMN "accountingPeriod" VARCHAR(20), ADD COLUMN "costKnown" BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN "dispatchedAt" TIMESTAMPTZ(3);
ALTER TABLE "AgentExecution" ADD CONSTRAINT "agent_reservation_positive" CHECK ("reservedUsdMicros">=0 AND "inputRateMicrosPerMillion">=0 AND "outputRateMicrosPerMillion">=0);
CREATE TABLE "AgentSchedule" ("id" UUID PRIMARY KEY,"agentId" UUID NOT NULL REFERENCES "Agent"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"enabled" BOOLEAN NOT NULL DEFAULT FALSE,"intervalSeconds" INTEGER NOT NULL DEFAULT 3600 CHECK ("intervalSeconds" BETWEEN 60 AND 2592000),"nextRunAt" TIMESTAMPTZ(3) NOT NULL,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL);
CREATE INDEX "AgentSchedule_enabled_nextRunAt_idx" ON "AgentSchedule"("enabled","nextRunAt");
CREATE TABLE "AgentBudgetPeriod" ("key" VARCHAR(100) PRIMARY KEY,"spentUsdMicros" BIGINT NOT NULL DEFAULT 0 CHECK ("spentUsdMicros">=0),"reservedUsdMicros" BIGINT NOT NULL DEFAULT 0 CHECK ("reservedUsdMicros">=0),"updatedAt" TIMESTAMPTZ(3) NOT NULL);
CREATE TABLE "AgentWorkerHeartbeat" ("id" VARCHAR(100) PRIMARY KEY,"lastSeenAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"status" VARCHAR(30) NOT NULL,"errorCode" VARCHAR(100));
